package com.anthony6996.hardcorecompass.storage;
import com.anthony6996.hardcorecompass.HardcoreCompassPlugin;import org.bukkit.configuration.file.YamlConfiguration;import java.io.*;import java.nio.file.*;import java.util.*;
public final class PlayerData{private final File file;private final YamlConfiguration data;private final int spawnHistoryLimit;public PlayerData(HardcoreCompassPlugin plugin){file=new File(plugin.getDataFolder(),"players.yml");spawnHistoryLimit=Math.max(1,plugin.getConfig().getInt("teleport.spawn-history-limit",10));if(!file.getParentFile().exists()&&!file.getParentFile().mkdirs())plugin.getLogger().warning("Could not create plugin data directory.");data=YamlConfiguration.loadConfiguration(file);}private String path(UUID id){return "players."+id;}public int getLives(UUID id,int fallback){return data.getInt(path(id)+".lives",fallback);}public void setLives(UUID id,int n){data.set(path(id)+".lives",n);}public int getDeaths(UUID id){return data.getInt(path(id)+".deaths",0);}public int incrementDeaths(UUID id){int n=getDeaths(id)+1;data.set(path(id)+".deaths",n);return n;}public boolean hasPreservedCompass(UUID id){return data.getBoolean(path(id)+".hasPreservedCompass",false);}public void setHasPreservedCompass(UUID id,boolean b){data.set(path(id)+".hasPreservedCompass",b);}public String getLanguage(UUID id){return data.getString(path(id)+".language");}public void setLanguage(UUID id,String l){data.set(path(id)+".language",l);}public boolean exists(UUID id){return data.contains(path(id)+".lives");}public void reset(UUID id){data.set(path(id),null);}public void resetDeaths(UUID id){data.set(path(id)+".deaths",0);data.set(path(id)+".hasPreservedCompass",false);}public void addUsedSpawn(UUID id,String coord){List<String> p=getUsedSpawns(id);p.remove(coord);p.add(coord);while(p.size()>spawnHistoryLimit)p.remove(0);data.set(path(id)+".usedSpawns",p);}public List<String> getUsedSpawns(UUID id){return new ArrayList<>(data.getStringList(path(id)+".usedSpawns"));}public void save(){File temp=new File(file.getParentFile(),"players.yml.tmp");try{data.save(temp);try{Files.move(temp.toPath(),file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(IOException ex){Files.move(temp.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING);}}catch(IOException ex){throw new IllegalStateException("Could not save players.yml",ex);}}}
